    /**
     * Method to retrieve the User via an FindUserQuery
     * @return 	query	FindUserQuery
     */
    @SuppressWarnings("unused")
    public User find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a User - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Users
     *
     * @param	query	FindAllUserQuery 
     * @return 	List<User> 
     */
    @SuppressWarnings("unused")
    public List<User> findAll( FindAllUserQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all User - {0}", exc.getMessage() );
    	}
    	return null;
    }


